PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL COLLATE NOCASE UNIQUE, username TEXT NOT NULL COLLATE NOCASE UNIQUE, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL, banned_until INTEGER, ban_reason TEXT, email_verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE profiles (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, display_name TEXT NOT NULL, bio TEXT NOT NULL DEFAULT '', avatar_id TEXT, banner_id TEXT, status TEXT NOT NULL DEFAULT '', website TEXT NOT NULL DEFAULT '', style TEXT NOT NULL DEFAULT 'classic', private INTEGER NOT NULL DEFAULT 0, allow_messages TEXT NOT NULL DEFAULT 'everyone' CHECK(allow_messages IN ('everyone','following','nobody')));
CREATE TABLE user_roles (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','moderator','administrator','owner')));
CREATE TABLE role_permissions (role TEXT NOT NULL, permission TEXT NOT NULL, PRIMARY KEY(role,permission));
INSERT INTO role_permissions VALUES ('moderator','moderate'),('administrator','moderate'),('administrator','premium'),('owner','moderate'),('owner','premium'),('owner','roles'),('owner','system');
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, label TEXT NOT NULL DEFAULT 'Browser');
CREATE INDEX sessions_user ON sessions(user_id);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE follows (follower_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, followed_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, PRIMARY KEY(follower_id,followed_id), CHECK(follower_id != followed_id));
CREATE INDEX follows_target ON follows(followed_id);
CREATE TABLE blocks (blocker_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, blocked_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id != blocked_id));
CREATE TABLE mutes (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, muted_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(user_id,muted_id));
CREATE TABLE posts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, content TEXT NOT NULL, parent_id TEXT REFERENCES posts(id) ON DELETE CASCADE, quote_id TEXT REFERENCES posts(id) ON DELETE SET NULL, reply_permission TEXT NOT NULL DEFAULT 'everyone' CHECK(reply_permission IN ('everyone','following','nobody')), created_at INTEGER NOT NULL, edited_at INTEGER, pinned INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0);
CREATE INDEX posts_feed ON posts(parent_id,created_at DESC,id DESC);
CREATE INDEX posts_author ON posts(user_id,created_at DESC,id DESC);
CREATE INDEX posts_parent ON posts(parent_id,created_at);
CREATE TABLE post_history (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, content TEXT NOT NULL, edited_at INTEGER NOT NULL);
CREATE TABLE uploads (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, content_type TEXT NOT NULL, size INTEGER NOT NULL CHECK(size BETWEEN 1 AND 512000), data TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX uploads_author ON uploads(user_id);
CREATE TABLE post_media (post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, upload_id TEXT NOT NULL REFERENCES uploads(id) ON DELETE CASCADE, position INTEGER NOT NULL, PRIMARY KEY(post_id,upload_id));
CREATE INDEX media_upload ON post_media(upload_id);
CREATE TABLE likes (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, PRIMARY KEY(user_id,post_id));
CREATE INDEX likes_post ON likes(post_id);
CREATE TABLE reposts (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, PRIMARY KEY(user_id,post_id));
CREATE INDEX reposts_post ON reposts(post_id);
CREATE TABLE bookmarks (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, PRIMARY KEY(user_id,post_id));
CREATE TABLE hashtags (tag TEXT NOT NULL, post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, PRIMARY KEY(tag,post_id));
CREATE INDEX hashtags_post ON hashtags(post_id);
CREATE TABLE drafts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, content TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX drafts_user ON drafts(user_id,updated_at DESC);
CREATE TABLE notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, actor_id TEXT REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, post_id TEXT REFERENCES posts(id) ON DELETE CASCADE, text TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, read_at INTEGER);
CREATE INDEX notifications_user ON notifications(user_id,created_at DESC);
CREATE TABLE conversations (id TEXT PRIMARY KEY, member_a TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, member_b TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, UNIQUE(member_a,member_b), CHECK(member_a < member_b));
CREATE INDEX conversations_a ON conversations(member_a);
CREATE INDEX conversations_b ON conversations(member_b);
CREATE TABLE messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, content TEXT NOT NULL, upload_id TEXT REFERENCES uploads(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, read_at INTEGER);
CREATE INDEX messages_thread ON messages(conversation_id,created_at DESC,id DESC);
CREATE TABLE reports (id TEXT PRIMARY KEY, reporter_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, target_user_id TEXT REFERENCES users(id) ON DELETE CASCADE, post_id TEXT REFERENCES posts(id) ON DELETE CASCADE, message_id TEXT REFERENCES messages(id) ON DELETE CASCADE, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at INTEGER NOT NULL);
CREATE INDEX reports_status ON reports(status,created_at DESC);
CREATE TABLE moderation_actions (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id) ON DELETE SET NULL, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, post_id TEXT REFERENCES posts(id) ON DELETE SET NULL, action TEXT NOT NULL, reason TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE appeals (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, reason TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE premium_grants (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, granted_by TEXT REFERENCES users(id) ON DELETE SET NULL, tier TEXT NOT NULL CHECK(tier IN ('premium','premium_plus','elite')), created_at INTEGER NOT NULL, expires_at INTEGER, revoked_at INTEGER);
CREATE INDEX premium_active ON premium_grants(user_id,revoked_at,expires_at);
CREATE TABLE premium_features (tier TEXT PRIMARY KEY, max_chars INTEGER NOT NULL, max_images INTEGER NOT NULL, max_pins INTEGER NOT NULL, bio_length INTEGER NOT NULL);
INSERT INTO premium_features VALUES ('free',500,2,1,160),('premium',2000,4,3,500),('premium_plus',5000,6,5,1000),('elite',10000,8,10,2000);
CREATE TABLE badges (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, badge TEXT NOT NULL CHECK(badge IN ('developer','moderator','founder','official','verified')), granted_by TEXT REFERENCES users(id) ON DELETE SET NULL, PRIMARY KEY(user_id,badge));
CREATE TABLE admin_audit_logs (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, target_id TEXT NOT NULL, detail TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX audit_created ON admin_audit_logs(created_at DESC);
CREATE TABLE user_settings (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, language TEXT NOT NULL DEFAULT 'ru', theme TEXT NOT NULL DEFAULT 'dark', hide_seen INTEGER NOT NULL DEFAULT 0, notifications INTEGER NOT NULL DEFAULT 1, reduced_motion INTEGER NOT NULL DEFAULT 0);
CREATE TABLE platform_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO platform_settings VALUES ('registration','true'),('maintenance','false'),('name','M² New Posted'),('rules','Уважайте друг друга. Не публикуйте спам, угрозы и чужие персональные данные.'),('announcement','');
CREATE TABLE analytics_events (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, viewer_id TEXT REFERENCES users(id) ON DELETE SET NULL, post_id TEXT REFERENCES posts(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK(type IN ('post_view','profile_view','follow','interaction')), created_at INTEGER NOT NULL, day TEXT NOT NULL, dedup TEXT NOT NULL UNIQUE);
CREATE INDEX analytics_owner ON analytics_events(user_id,created_at DESC);
CREATE INDEX analytics_viewer ON analytics_events(viewer_id,type,post_id);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE password_resets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE recent_searches (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, query TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(user_id,query));
